import unittest
from storage import Storage

class StorageContractTests(unittest.TestCase):
    def test_missing_spark_raises_without_local_fallback(self):
        calls = []
        def local_reader():
            calls.append('local')
            return [{'origin': 'local'}]
        with self.assertRaisesRegex(RuntimeError, 'Spark session required'):
            Storage().table(None, 'orders', local_reader)
        self.assertEqual(calls, [])

    def test_supplied_session_reads_named_table(self):
        names = []
        class Rows:
            def collect(self):
                return [{'id': 7}]
        class Session:
            def table(self, name):
                names.append(name)
                return Rows()
        self.assertEqual(Storage().table(Session(), 'orders', None), [{'id': 7}])
        self.assertEqual(names, ['orders'])

